import re, sys, os

KEY_RE = re.compile(r'^(\s*)((?:"[^"]*")|(?:\'[^\']*\')|([^:#]*?)):\s*(.*)$')

class Node:
    def __init__(self, key, start, indent, parent):
        self.key = key
        self.start = start
        self.indent = indent
        self.parent = parent
        self.children = []
        self.end = start + 1
        self.value_lines = []

def parse(lines):
    root = Node("", -1, -1, None)
    stack = [root]
    i = 0
    n = len(lines)
    while i < n:
        raw = lines[i].rstrip("\n")
        stripped = raw.strip()
        if stripped == "" or stripped.startswith("#"):
            i += 1
            continue
        m = KEY_RE.match(raw)
        if not m:
            # sequence item or continuation: attach to current node
            stack[-1].value_lines.append(i)
            i += 1
            continue
        indent = len(m.group(1))
        key = m.group(2)
        # pop stack to the right level
        while stack[-1].indent >= indent:
            stack.pop()
        node = Node(key, i, indent, stack[-1])
        stack[-1].children.append(node)
        stack.append(node)
        value = m.group(4)
        if value == "":
            i += 1
            # children follow (or nothing)
            node.end = i
            continue
        if value in ("|", "|-", "|+", ">", ">-", ">+"):
            i += 1
            while i < n:
                l = lines[i].rstrip("\n")
                if l.strip() == "" or len(l) - len(l.lstrip()) > indent:
                    i += 1
                else:
                    break
            node.end = i
        else:
            i += 1
            node.end = i
    # propagate ends up
    def fix(node):
        if node.children:
            node.end = max(c.end for c in node.children)
        else:
            node.end = node.start + 1
        for c in node.children:
            fix(c)
    fix(root)
    return root

def find_path(node, parts):
    if not parts:
        return node
    for c in node.children:
        if c.key == parts[0]:
            return find_path(c, parts[1:])
    return None

def collect_leaves(node, prefix, acc):
    for c in node.children:
        path = prefix + [c.key]
        if c.children:
            collect_leaves(c, path, acc)
        else:
            acc.append((path, c))

def main(files, keys_to_remove):
    to_remove = set(keys_to_remove)
    for f in files:
        with open(f) as fh:
            lines = fh.readlines()
        root = parse(lines)
        leaves = []
        collect_leaves(root, [], leaves)
        delete = set()
        remove_parents = []
        for path, node in leaves:
            full = ".".join(path[1:])
            if full in to_remove:
                delete.update(range(node.start, node.end))
                remove_parents.append(node)
        # prune parents that become empty
        changed = True
        while changed:
            changed = False
            for node in remove_parents:
                p = node.parent
                while p is not None and p.parent is not None:
                    child_lines = set()
                    for c in p.children:
                        child_lines.update(range(c.start, c.end))
                    if child_lines and child_lines.issubset(delete):
                        delete.update(range(p.start, p.start + 1))
                        changed = True
                    p = p.parent
        if delete:
            new = [l for idx, l in enumerate(lines) if idx not in delete]
            with open(f, "w") as fh:
                fh.writelines(new)
            print(f"{f}: removed {len(delete)} lines")

if __name__ == "__main__":
    files = sys.argv[1].split(",")
    keys = [k.strip() for k in open(sys.argv[2]) if k.strip() and not k.startswith("Key")]
    main(files, keys)
