        if value == "":
            i += 1
            node.end = i
            continue
        if value in ("|", "|-", "|+", ">", ">-", ">+"):
            i += 1
            while i < n:
                l = lines[i].rstrip("\n")
                if l.strip() == "" or len(l) - len(l.lstrip()) > indent:
                    i += 1
                else:
                    break
            node.end = i
        else:
            i += 1
            node.end = i
    def fix(node):
        if node.children:
            node.end = max(c.end for c in node.children)
        else:
            node.end = node.start + 1
        for c in node.children:
            fix(c)
    fix(root)
    return root

def collect_leaves(node, prefix, acc):
    for c in node.children:
        path = prefix + [c.key]
        if c.children:
            collect_leaves(c, path, acc)
        else:
            acc.append((path, c))

def main(files, keys_to_remove):
    to_remove = set(keys_to_remove)
    total = 0
    for f in files:
        with open(f) as fh:
            lines = fh.readlines()
        root = parse(lines)
        leaves = []
        collect_leaves(root, [], leaves)
        delete = set()
        for path, node in leaves:
            full = ".".join(path[1:])
            if full in to_remove:
                delete.update(range(node.start, node.end))
                node.deleted_leaves = node.end - node.start
                p = node.parent
                while p is not None and p.parent is not None:
                    p.deleted_leaves += node.deleted_leaves
                    p = p.parent
        # prune parents whose whole block is deleted
        stack = [c for c in root.children]
        while stack:
            nd = stack.pop()
            if nd.children:
                stack.extend(nd.children)
            else:
                continue
        def prune(node):
            if not node.children:
                return
            for c in node.children:
                prune(c)
            # a parent line is deleted when every child leaf is deleted
            total_leaves = [0]
            def count(n2):
                if n2.children:
                    for c in n2.children:
                        count(c)
                else:
                    total_leaves[0] += 1
            count(node)
            if total_leaves[0] == node.deleted_leaves:
                delete.add(node.start)
        prune(root)
        if delete:
            new = [l for idx, l in enumerate(lines) if idx not in delete]
            with open(f, "w") as fh:
                fh.writelines(new)
            total += len(delete)
            print(f"{f}: removed {len(delete)} lines")

if __name__ == "__main__":
    files = sys.argv[1].split(",")
    keys = [k.strip() for k in open(sys.argv[2]) if k.strip() and not k.startswith("Key")]
    main(files, keys)
