import re, sys

KEY_RE = re.compile(r'^(\s*)((?:"[^"]*")|(?:\'[^\']*\')|([^:#]*?)):\s*(.*)$')

class Node:
    __slots__ = ("key", "start", "indent", "parent", "children", "end")
    def __init__(self, key, start, indent, parent):
