        self.start = start
        self.indent = indent
        self.parent = parent
        self.children = []
        self.end = start + 1

def parse(lines):
    root = Node("", -1, -1, None)
    stack = [root]
    i = 0
    n = len(lines)
    while i < n:
        raw = lines[i].rstrip("\n")
        stripped = raw.strip()
        if stripped == "" or stripped.startswith("#"):
            i += 1
            continue
        m = KEY_RE.match(raw)
        if not m:
            i += 1
            continue
        indent = len(m.group(1))
        key = m.group(2)
        while stack[-1].indent >= indent:
            stack.pop()
        node = Node(key, i, indent, stack[-1])
        stack[-1].children.append(node)
        stack.append(node)
        value = m.group(4)
        if value == "":
            i += 1
            node.end = i
            continue
        if value in ("|", "|-", "|+", ">", ">-", ">+"):
            i += 1
            while i < n:
                l = lines[i].rstrip("\n")
                if l.strip() == "" or len(l) - len(l.lstrip()) > indent:
                    i += 1
                else:
                    break
            node.end = i
        else:
            i += 1
            node.end = i
    def fix(node):
        if node.children:
            node.end = max(c.end for c in node.children)
        else:
            node.end = node.start + 1
        for c in node.children:
            fix(c)
    fix(root)
    return root

def find(node, parts):
    cur = node
    for p in parts:
        nxt = None
        for c in cur.children:
            if c.key == p:
                nxt = c
                break
        if nxt is None:
            return None
        cur = nxt
    return cur

def main(files, keys_to_remove):
    to_remove = set(keys_to_remove)
    for f in files:
        with open(f) as fh:
            lines = fh.readlines()
        root = parse(lines)
        delete = set()
        # count deleted lines in each subtree
        def mark(node):
            d = 0
            for c in node.children:
                d += mark(c)
            if node.start in delete:
                d += (node.end - node.start)
            return d
        for key in sorted(to_remove, key=len, reverse=True):
            parts = key.split(".")
            node = find(root, parts)
            if node is None:
                continue
            # mark whole subtree
            def mark_sub(n2):
                delete.update(range(n2.start, n2.end))
                for c in n2.children:
                    mark_sub(c)
